import { useTranslation } from 'react-i18next';
import { useState, useRef, useEffect } from 'react';
import { FaArrowLeft } from 'react-icons/fa6';
import { saveAs } from 'file-saver';
import { VersionPicker } from './VersionPicker';
import { Text } from '~/components/ui/text';
import { Metadata } from '~/components/layout/Metadata';
import { Box, HStack, Stack, styled } from 'styled-system/jsx';

import { ChartViewer, type ChartViewerHandles } from '~/components/ChartViewer';
import { Button } from '~/components/ui/button';
import { RadioButtonGroup } from '~/components/ui/radio-button-group';
import { Link } from '~/components/ui/link';
import { getAlbumArtPublicPath } from '~/utils/assets';
import { Checkbox } from '~/components/ui/checkbox';

import type { PageData } from '~/pages/@id/+data';

export function ChartDisplayPage({ chartInfo, chartData, versions }: PageData) {
  const { t } = useTranslation();
  const chartViewerRef = useRef<ChartViewerHandles>(null);

  const getInitialDifficulty = (): 1 | 2 | 3 | 4 => {
    const difficultySearchParam = new URLSearchParams(window.location.search).get('difficulty');
    if (difficultySearchParam && ['1', '2', '3', '4'].includes(difficultySearchParam)) {
      return parseInt(difficultySearchParam, 10) as 1 | 2 | 3 | 4;
    }
    return 4;
  };

  const [difficulty, setDifficulty] = useState<1 | 2 | 3 | 4>(1);
  const [showJacket, setShowJacket] = useState(true);

  const chart = chartData[difficulty];
  const title = chartInfo.title;

  const difficultyLabels = {
    1: 'NORMAL',
    2: 'HARD',
    3: 'EXPERT',
    4: 'MASTER'
  };

  const options = ([1, 2, 3, 4] as const).map((diffKey) => {
    const difficultyValue =
      chartInfo.difficulty[
        difficultyLabels[diffKey].toLowerCase() as keyof typeof chartInfo.difficulty
      ];
    const maxComboValue =
      chartInfo.maxCombo[
        difficultyLabels[diffKey].toLowerCase() as keyof typeof chartInfo.maxCombo
      ];
    return {
      label: difficultyLabels[diffKey],
      value: diffKey,
      difficulty: difficultyValue,
      maxCombo: maxComboValue
    };
  });

  const currentDifficultyLabel = difficultyLabels[difficulty];
  const fileNamePrefix = `${title} - ${currentDifficultyLabel}`;

  const baseDescription = chartInfo.description;
  const difficultyDetailsString = `| Normal: ${chartInfo.difficulty.normal} | Hard: ${chartInfo.difficulty.hard} | Expert: ${chartInfo.difficulty.expert} | Master: ${chartInfo.difficulty.master} |`;
  const pageDescription = `${baseDescription}\n${difficultyDetailsString}`;

  let feverLengthDetails = '';
  if (chartInfo.feverSection && chartInfo.feverSection > 0) {
    const feverSectionIdx = chartInfo.feverSection;
    const sectionTimesArray = chartInfo.sectionTimes;
    const songDuration = chartInfo.duration;

    // Ensure feverSectionIdx - 1 is a valid starting index for sectionTimesArray
    if (feverSectionIdx - 1 < sectionTimesArray.length) {
      const startTime = sectionTimesArray[feverSectionIdx - 1];
      let endTime;

      if (feverSectionIdx < sectionTimesArray.length) {
        endTime = sectionTimesArray[feverSectionIdx];
      } else {
        // feverSectionIdx is >= sectionTimesArray.length, use song duration
        endTime = songDuration;
      }

      const feverLengthMs = endTime - startTime;
      if (feverLengthMs > 0) {
        feverLengthDetails = `${t('fever_length', 'Fever Length')}: ${(feverLengthMs / 1000).toFixed(2)} ${t('seconds')}`;
      }
    }
  }

  const descriptionParts: string[] = [];
  if (chartInfo.description) {
    descriptionParts.push(chartInfo.description);
  }

  if (chart && chart[8] && chart[8].length > 0) {
    const bpmValues = chart[8].map((e) => e.Bpm).join(',');
    descriptionParts.push(`BPM: ${bpmValues}`);
  }

  descriptionParts.push(`${(chartInfo.duration / 1000).toFixed(2)} ${t('seconds')}`);

  if (feverLengthDetails) {
    descriptionParts.push(feverLengthDetails);
  }
  const chartDisplayString = descriptionParts.join(' | ');

  const handleSaveImage = () => {
    chartViewerRef.current?.getCanvasBlob(
      (blob) => {
        if (blob) {
          saveAs(blob, `${fileNamePrefix}_chart.png`);
        } else {
        }
      },
      'image/png',
      1,
      showJacket
    );
  };

  const handleOpenInNewTab = () => {
    chartViewerRef.current?.getCanvasBlob(
      (blob) => {
        if (blob) {
          const objectUrl = URL.createObjectURL(blob);
          const newTab = window.open(objectUrl, '_blank');
          if (newTab) {
            newTab.addEventListener('pagehide', () => URL.revokeObjectURL(objectUrl), {
              once: true
            });
          } else {
            URL.revokeObjectURL(objectUrl);
          }
        } else {
        }
      },
      'image/png',
      1,
      showJacket
    );
  };

  useEffect(() => {
    setDifficulty(getInitialDifficulty());
  }, []);

  return (
    <>
      <Metadata
        title={`${chartInfo.title} | ${t('site_name')}`}
        description={pageDescription}
        imageUrl={chartInfo?.id ? getAlbumArtPublicPath(chartInfo.id) : undefined}
      />
      <Stack alignItems="center" w="full" _print={{ display: 'none' }}>
        <Box>
          <Link href="/">
            <FaArrowLeft />
            {t('back_to_list')}
          </Link>
        </Box>
        <Text textAlign="center" fontSize="3xl" fontWeight="bold">
          {title}
        </Text>
        <Box w="48" h="48" my="4">
          <styled.img
            src={getAlbumArtPublicPath(chartInfo.id)}
            alt={`${title} album art`}
            objectFit="contain"
            w="full"
            h="full"
          />
        </Box>
        <Text textAlign="center">{chartDisplayString}</Text>
        <RadioButtonGroup.Root
          size="xl"
          value={String(difficulty)}
          onValueChange={(v) => setDifficulty(Number(v.value) as 1 | 2 | 3 | 4)}
          justifyContent="center"
          alignItems="center"
        >
          {options.map((option) => (
            <RadioButtonGroup.Item
              key={option.value}
              value={option.value + ''}
              borderColor={`difficulty.${option.label.toLowerCase()}.fg`}
              borderWidth="1px"
              height="fit-content"
              p="2"
              color={`difficulty.${option.label.toLowerCase()}.fg`}
              background="unset"
              borderStyle="solid"
              _checked={{
                backgroundColor: `difficulty.${option.label.toLowerCase()}.bg`,
                color: 'fg.default',
                borderColor: `difficulty.${option.label.toLowerCase()}.bg`
              }}
            >
              <RadioButtonGroup.ItemControl />
              <RadioButtonGroup.ItemText>
                <Stack gap="0" alignItems="center" textAlign="center">
                  <Stack gap="0.5" direction="row" alignItems="baseline">
                    <Text fontSize="xs">Lv.</Text>
                    <Text fontSize="xl" fontWeight="bold" lineHeight="1">
                      {option.difficulty}
                    </Text>
                    <Text fontSize="xs" lineHeight="1">
                      ({option.maxCombo})
                    </Text>
                  </Stack>
                  <Text fontSize="sm" lineHeight="1.2">
                    {option.label}
                  </Text>
                </Stack>
              </RadioButtonGroup.ItemText>
              <RadioButtonGroup.ItemHiddenInput />
            </RadioButtonGroup.Item>
          ))}
        </RadioButtonGroup.Root>
        {versions.length > 0 && <VersionPicker id={chartInfo.id.toString()} versions={versions} />}
        <HStack gap="4" justifyContent="center" mt="4">
          <Checkbox
            checked={showJacket}
            onCheckedChange={(e) => setShowJacket(e.checked as boolean)}
          >
            {t('show_jacket')}
          </Checkbox>
          <Button onClick={handleSaveImage} disabled={!chart}>
            {t('save_image')}
          </Button>
          <Button onClick={handleOpenInNewTab} variant="outline" disabled={!chart}>
            {t('open_image_new_tab')}
          </Button>
        </HStack>
        <Box w="full" mt="4" overflowX="auto">
          <Box pointerEvents="none">
            <ChartViewer
              ref={chartViewerRef}
              chart={chart}
              feverSection={chartInfo?.feverSection}
              sectionTimes={chartInfo?.sectionTimes}
              imageUrl={
                showJacket && chartInfo?.id ? getAlbumArtPublicPath(chartInfo.id) : undefined
              }
            />
          </Box>
        </Box>
      </Stack>
    </>
  );
}
